pub fn group_count(w: &[u8], st: &mut [usize], k: usize, t: usize, e: usize) -> usize {
    if ((t >= e) || (w[(t) as usize] != B_LPAREN)) {
        return NONE;
    }
    let mut q: usize = (t + 1);
    let mut n: usize = 0;
    let mut result: usize = NONE;
    let mut go: bool = true;
    while go {
        let a: usize = tk(w, q, e);
        if (a >= e) {
            go = false;
        } else {
            if (w[(a) as usize] == B_RPAREN) {
                st[(GROUP_END) as usize] = (a + 1);
                result = n;
                go = false;
            } else {
                if (is_punct(w[(a) as usize]) || !(parse_num(w, a, tk_end(w, a, e), st))) {
                    reject(st, Y_NUMBER, k, a);
                    go = false;
                } else {
                    n = (n + 1);
                    q = tk_end(w, a, e);
                }
            }
        }
    }
    return result;
}

pub fn source(w: &[u8], st: &mut [usize], k: usize, kind: usize, t1: usize, e: usize) -> () {
    count(st, kind);
    let mut q: usize = after_word(w, t1, e, 1);
    if (q == NONE) {
        reject(st, Y_FIELDS, k, NONE);
        return ();
    }
    let mut wave: usize = WV_DC;
    let mut seen: usize = 0;
    let mut go: bool = true;
    while go {
        let t: usize = tk(w, q, e);
        if (t >= e) {
            go = false;
        } else {
            let te: usize = tk_end(w, t, e);
            if ci_is(w, t, te, b"dc") {
                if !(need_num(w, st, k, tk(w, te, e), e)) {
                    return ();
                }
                q = tk_end(w, tk(w, te, e), e);
            } else {
                if ((ci_is(w, t, te, b"pulse") || ci_is(w, t, te, b"sin")) || ci_is(w, t, te, b"pwl")) {
                    let n: usize = group_count(w, st, k, tk(w, te, e), e);
                    if (n == NONE) {
                        reject(st, Y_FIELDS, k, t);
                        return ();
                    }
                    let mut ok: bool = false;
                    if ci_is(w, t, te, b"pulse") {
                        wave = WV_PULSE;
                        ok = ((n >= 2) && (n <= 7));
                    }
                    if ci_is(w, t, te, b"sin") {
                        wave = WV_SIN;
                        ok = ((n >= 3) && (n <= 6));
                    }
                    if ci_is(w, t, te, b"pwl") {
                        wave = WV_PWL;
                        ok = ((n >= 2) && ((n % 2) == 0));
                    }
                    if !(ok) {
                        reject(st, Y_FIELDS, k, t);
                        return ();
                    }
                    q = st[(GROUP_END) as usize];
                } else {
                    if (((seen == 0) && !(is_punct(w[(t) as usize]))) && parse_num(w, t, te, st)) {
                        q = te;
                    } else {
                        reject(st, Y_SOURCE, k, t);
                        return ();
                    }
                }
            }
            seen = (seen + 1);
        }
    }
    if (seen == 0) {
        reject(st, Y_FIELDS, k, NONE);
    } else {
        st[((WAVE + wave)) as usize] = (st[((WAVE + wave)) as usize] + 1);
    }
}

pub fn vcvs(w: &[u8], st: &mut [usize], k: usize, t1: usize, e: usize) -> () {
    count(st, K_E);
    let g: usize = word_at(w, t1, e, 4);
    if (g == NONE) {
        reject(st, Y_E, k, NONE);
        return ();
    }
    let q: usize = tk_end(w, g, e);
    if (tk(w, q, e) < e) {
        reject(st, Y_E, k, tk(w, q, e));
    } else {
        if !(parse_num(w, g, q, st)) {
            reject(st, Y_E, k, g);
        }
    }
}

pub fn xparse(w: &[u8], st: &mut [usize], k: usize) -> bool {
    let e: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize];
    let mut q: usize = tk_end(w, st[(((CARD0 + (k * CARD_SLOTS)) + C_A)) as usize], e);
    let mut words: usize = 0;
    let mut ma: usize = 0;
    let mut mb: usize = 0;
    let mut pairs: usize = e;
    let mut go: bool = true;
    while go {
        let t: usize = tk(w, q, e);
        if (t >= e) {
            go = false;
        } else {
            let te: usize = tk_end(w, t, e);
            let nx: usize = tk(w, te, e);
            if (((nx < e) && (w[(nx) as usize] == B_EQ)) && !(is_punct(w[(t) as usize]))) {
                pairs = t;
                go = false;
            } else {
                if is_punct(w[(t) as usize]) {
                    pairs = t;
                    go = false;
                } else {
                    words = (words + 1);
                    ma = t;
                    mb = te;
                    q = te;
                }
            }
        }
    }
    st[(XN) as usize] = 0;
    if (words > 0) {
        st[(XN) as usize] = (words - 1);
    }
    st[(XA) as usize] = ma;
    st[(XB) as usize] = mb;
    st[(XP) as usize] = pairs;
    return (words >= 2);
}

pub fn pdk_class(w: &[u8], a: usize, b: usize) -> usize {
    if ci_is(w, a, b, b"sg13_lv_nmos") {
        return X_NMOS;
    }
    if ci_is(w, a, b, b"sg13_lv_pmos") {
        return X_PMOS;
    }
    if ci_is(w, a, b, b"cap_cmim") {
        return X_MIM;
    }
    return X_NONE;
}

pub fn x_card(w: &[u8], st: &mut [usize], k: usize) -> () {
    st[(N_XCARDS) as usize] = (st[(N_XCARDS) as usize] + 1);
    if !(xparse(w, st, k)) {
        reject(st, Y_FIELDS, k, NONE);
        return ();
    }
    check_params(w, st, k, st[(XP) as usize], st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize], 15, true);
}

pub fn element(w: &[u8], st: &mut [usize], k: usize, t0: usize, t1: usize, e: usize) -> () {
    let c: u8 = lower(w[(t0) as usize]);
    if (c == 114) {
        passive(w, st, k, K_R, t1, e);
    } else {
        if (c == 99) {
            passive(w, st, k, K_C, t1, e);
        } else {
            if (c == 108) {
                passive(w, st, k, K_L, t1, e);
            } else {
                if (c == 118) {
                    source(w, st, k, K_V, t1, e);
                } else {
                    if (c == 105) {
                        source(w, st, k, K_I, t1, e);
                    } else {
                        if (c == 101) {
                            vcvs(w, st, k, t1, e);
                        } else {
                            if (c == 120) {
                                x_card(w, st, k);
                            } else {
                                if (c == 98) {
                                    reject(st, Y_B, k, NONE);
                                } else {
                                    reject(st, Y_ELEMENT, k, NONE);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn dir_is(w: &[u8], a: usize, b: usize, one: &[u8], two: &[u8]) -> bool {
    return (ci_is(w, a, b, one) || ci_is(w, a, b, two));
}

pub fn find_def(w: &[u8], st: &mut [usize], a: usize, b: usize, scope: usize) -> usize {
    let mut s: usize = scope;
    let mut found: usize = NONE;
    let mut go: bool = true;
    while go {
        let mut d: usize = 0;
        while (go && (d < st[(NDEF) as usize])) {
            if ((st[(((DEF0 + (d * DEF_SLOTS)) + D_PARENT)) as usize] == s) && same_ci(w, a, b, st[(((DEF0 + (d * DEF_SLOTS)) + D_NAME_A)) as usize], st[(((DEF0 + (d * DEF_SLOTS)) + D_NAME_B)) as usize])) {
                found = d;
                go = false;
            }
            d = (d + 1);
        }
        if go {
            if ((s == NONE) || (s == SCOPE_CTL)) {
                go = false;
            } else {
                s = st[(((DEF0 + (s * DEF_SLOTS)) + D_PARENT)) as usize];
            }
        }
    }
    st[(DEF_HIT) as usize] = found;
    return found;
}

pub fn d_subckt(w: &[u8], st: &mut [usize], k: usize, t1: usize, e: usize) -> () {
    let na: usize = word_at(w, t1, e, 0);
    if (na == NONE) {
        reject(st, Y_FIELDS, k, NONE);
        return ();
    }
    let nb: usize = tk_end(w, na, e);
    let mut ports: usize = 0;
    let mut q: usize = nb;
    let mut go: bool = true;
    while go {
        let t: usize = tk(w, q, e);
        if (t >= e) {
            go = false;
        } else {
            let te: usize = tk_end(w, t, e);
            let nx: usize = tk(w, te, e);
            if (is_punct(w[(t) as usize]) || ((nx < e) && (w[(nx) as usize] == B_EQ))) {
                reject(st, Y_SUBPARAM, k, t);
                go = false;
            } else {
                ports = (ports + 1);
                q = te;
            }
        }
    }
    if (st[(NDEF) as usize] >= MAXDEF) {
        reject(st, Y_SIZE, k, NONE);
        return ();
    }
    let dup: usize = find_def(w, st, na, nb, st[(CUR) as usize]);
    if ((dup != NONE) && (st[(((DEF0 + (dup * DEF_SLOTS)) + D_PARENT)) as usize] == st[(CUR) as usize])) {
        reject(st, Y_DUP, k, na);
    }
    let d: usize = st[(NDEF) as usize];
    st[(((DEF0 + (d * DEF_SLOTS)) + D_NAME_A)) as usize] = na;
    st[(((DEF0 + (d * DEF_SLOTS)) + D_NAME_B)) as usize] = nb;
    st[(((DEF0 + (d * DEF_SLOTS)) + D_NPORTS)) as usize] = ports;
    st[(((DEF0 + (d * DEF_SLOTS)) + D_FIRST)) as usize] = k;
    st[(((DEF0 + (d * DEF_SLOTS)) + D_LAST)) as usize] = NONE;
    st[(((DEF0 + (d * DEF_SLOTS)) + D_PARENT)) as usize] = st[(CUR) as usize];
    st[(NDEF) as usize] = (d + 1);
    st[(CUR) as usize] = d;
}

pub fn d_ends(w: &[u8], st: &mut [usize], k: usize, t1: usize, e: usize) -> () {
    let d: usize = st[(CUR) as usize];
    if (d == NONE) {
        reject(st, Y_ENDS, k, NONE);
        return ();
    }
    let na: usize = word_at(w, t1, e, 0);
    if ((na != NONE) && !(same_ci(w, na, tk_end(w, na, e), st[(((DEF0 + (d * DEF_SLOTS)) + D_NAME_A)) as usize], st[(((DEF0 + (d * DEF_SLOTS)) + D_NAME_B)) as usize]))) {
        reject(st, Y_ENDS, k, na);
    }
    st[(((DEF0 + (d * DEF_SLOTS)) + D_LAST)) as usize] = k;
    st[(CUR) as usize] = st[(((DEF0 + (d * DEF_SLOTS)) + D_PARENT)) as usize];
}

pub fn only_words(w: &[u8], t1: usize, e: usize, n: usize) -> bool {
    let q: usize = after_word(w, t1, e, (n - 1));
    if (q == NONE) {
        return false;
    }
    return (tk(w, q, e) >= e);
}

pub fn d_options(w: &[u8], st: &mut [usize], k: usize, t1: usize, e: usize) -> () {
    st[(N_OPT) as usize] = (st[(N_OPT) as usize] + 1);
    let mut q: usize = t1;
    let mut go: bool = true;
    let mut seen: usize = 0;
    while go {
        let t: usize = tk(w, q, e);
        if (t >= e) {
            go = false;
        } else {
            let te: usize = tk_end(w, t, e);
            let eq: usize = tk(w, te, e);
            if (((is_punct(w[(t) as usize]) || !(ci_is(w, t, te, b"temp"))) || (eq >= e)) || (w[(eq) as usize] != B_EQ)) {
                reject(st, Y_OPTION, k, t);
                go = false;
            } else {
                if !(need_num(w, st, k, tk(w, (eq + 1), e), e)) {
                    go = false;
                } else {
                    st[(TEMP_CARD) as usize] = k;
                    seen = (seen + 1);
                    q = tk_end(w, tk(w, (eq + 1), e), e);
                }
            }
        }
    }
    if (seen == 0) {
        reject(st, Y_FIELDS, k, NONE);
    }
}

pub fn pairs(w: &[u8], st: &mut [usize], k: usize, t1: usize, e: usize, groups: bool) -> usize {
    let mut q: usize = t1;
    let mut n: usize = 0;
    let mut go: bool = true;
    while go {
        let t: usize = tk(w, q, e);
        if (t >= e) {
            go = false;
        } else {
            let mut eq: usize = NONE;
            let te: usize = tk_end(w, t, e);
            if groups {
                let lp: usize = tk(w, te, e);
                let nd: usize = tk(w, (lp + 1), e);
                let rp: usize = tk(w, tk_end(w, nd, e), e);
                let q2: usize = tk(w, (rp + 1), e);
                if ((((((((ci_is(w, t, te, b"v") && (lp < e)) && (w[(lp) as usize] == B_LPAREN)) && (nd < e)) && !(is_punct(w[(nd) as usize]))) && (rp < e)) && (w[(rp) as usize] == B_RPAREN)) && (q2 < e)) && (w[(q2) as usize] == B_EQ)) {
                    eq = q2;
                }
            } else {
                let q2: usize = tk(w, te, e);
                if ((!(is_punct(w[(t) as usize])) && (q2 < e)) && (w[(q2) as usize] == B_EQ)) {
                    eq = q2;
                }
            }
            if (eq == NONE) {
                reject(st, Y_FIELDS, k, t);
                go = false;
            } else {
                if !(need_num(w, st, k, tk(w, (eq + 1), e), e)) {
                    go = false;
                } else {
                    n = (n + 1);
                    q = tk_end(w, tk(w, (eq + 1), e), e);
                }
            }
        }
    }
    if ((n == 0) && (st[(ERR_LINE) as usize] == 0)) {
        reject(st, Y_FIELDS, k, NONE);
    }
    return n;
}

pub fn tran_args(w: &[u8], st: &mut [usize], k: usize, p: usize, e: usize) -> () {
    let mut q: usize = p;
    let mut n: usize = 0;
    let mut go: bool = true;
    while go {
        let t: usize = tk(w, q, e);
        if (t >= e) {
            go = false;
        } else {
            let te: usize = tk_end(w, t, e);
            if ((n >= 2) && ci_is(w, t, te, b"uic")) {
                q = te;
            } else {
                if (((n < 4) && !(is_punct(w[(t) as usize]))) && parse_num(w, t, te, st)) {
                    n = (n + 1);
                    q = te;
                } else {
                    reject(st, Y_NUMBER, k, t);
                    go = false;
                }
            }
        }
    }
    if (n < 2) {
        reject(st, Y_FIELDS, k, NONE);
    }
}

pub fn directive(w: &[u8], st: &mut [usize], k: usize, t0: usize, t1: usize, e: usize) -> () {
    if ci_is(w, t0, t1, b".subckt") {
        d_subckt(w, st, k, t1, e);
    } else {
        if ci_is(w, t0, t1, b".ends") {
            d_ends(w, st, k, t1, e);
        } else {
            if ci_is(w, t0, t1, b".end") {
            } else {
                if ci_is(w, t0, t1, b".control") {
                    if (st[(CUR) as usize] != NONE) {
                        reject(st, Y_CTLIN, k, NONE);
                    }
                    st[(CTL_CARD) as usize] = k;
                } else {
                    if ci_is(w, t0, t1, b".lib") {
                        st[(N_LIB) as usize] = (st[(N_LIB) as usize] + 1);
                        if !(only_words(w, t1, e, 2)) {
                            reject(st, Y_FIELDS, k, NONE);
                        }
                    } else {
                        if dir_is(w, t0, t1, b".include", b".inc") {
                            st[(N_INC) as usize] = (st[(N_INC) as usize] + 1);
                            if !(only_words(w, t1, e, 1)) {
                                reject(st, Y_FIELDS, k, NONE);
                            }
                        } else {
                            if dir_is(w, t0, t1, b".options", b".option") {
                                d_options(w, st, k, t1, e);
                            } else {
                                if (ci_cat(w, t0, t1, b".par", b"am") || ci_cat(w, t0, t1, b".par", b"ams")) {
                                    st[(N_PARAM) as usize] = (st[(N_PARAM) as usize] + pairs(w, st, k, t1, e, false));
                                } else {
                                    if ci_is(w, t0, t1, b".tran") {
                                        st[(N_TRAN) as usize] = (st[(N_TRAN) as usize] + 1);
                                        tran_args(w, st, k, t1, e);
                                    } else {
                                        if ci_is(w, t0, t1, b".ic") {
                                            st[(N_IC) as usize] = (st[(N_IC) as usize] + pairs(w, st, k, t1, e, true));
                                        } else {
                                            if ci_is(w, t0, t1, b".nodeset") {
                                                st[(N_NODESET) as usize] = (st[(N_NODESET) as usize] + pairs(w, st, k, t1, e, true));
                                            } else {
                                                if ci_is(w, t0, t1, b".save") {
                                                    st[(N_SAVE) as usize] = (st[(N_SAVE) as usize] + 1);
                                                } else {
                                                    if ci_is(w, t0, t1, b".global") {
                                                        st[(N_GLOBAL) as usize] = (st[(N_GLOBAL) as usize] + 1);
                                                        if (word_at(w, t1, e, 0) == NONE) {
                                                            reject(st, Y_FIELDS, k, NONE);
                                                        }
                                                    } else {
                                                        reject(st, Y_DIRECTIVE, k, NONE);
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn inert_command(w: &[u8], a: usize, b: usize) -> bool {
    return (((((((((((((((ci_is(w, a, b, b"let") || ci_is(w, a, b, b"plot")) || ci_is(w, a, b, b"set")) || ci_is(w, a, b, b"unset")) || ci_is(w, a, b, b"write")) || ci_is(w, a, b, b"run")) || ci_is(w, a, b, b"print")) || ci_is(w, a, b, b"echo")) || ci_is(w, a, b, b"wrdata")) || ci_is(w, a, b, b"setplot")) || ci_is(w, a, b, b"display")) || ci_is(w, a, b, b"destroy")) || ci_is(w, a, b, b"quit")) || ci_is(w, a, b, b"exit")) || ci_is(w, a, b, b"save")) || ci_is(w, a, b, b"hardcopy"));
}

pub fn control_card(w: &[u8], st: &mut [usize], k: usize, t0: usize, t1: usize, e: usize) -> () {
    if ci_is(w, t0, t1, b".endc") {
        st[(CTL_CARD) as usize] = NONE;
    } else {
        if ci_is(w, t0, t1, b"tran") {
            st[(N_TRAN_CTL) as usize] = (st[(N_TRAN_CTL) as usize] + 1);
            tran_args(w, st, k, t1, e);
        } else {
            if inert_command(w, t0, t1) {
                st[(N_CTLCMD) as usize] = (st[(N_CTLCMD) as usize] + 1);
            } else {
                reject(st, Y_CTL, k, t0);
            }
        }
    }
}

pub fn scan_card(w: &[u8], st: &mut [usize], k: usize) -> () {
    let a: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_A)) as usize];
    let e: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize];
    let t0: usize = tk(w, a, e);
    let t1: usize = tk_end(w, t0, e);
    if (st[(CTL_CARD) as usize] != NONE) {
        st[(((CARD0 + (k * CARD_SLOTS)) + C_SCOPE)) as usize] = SCOPE_CTL;
        control_card(w, st, k, t0, t1, e);
        return ();
    }
    st[(((CARD0 + (k * CARD_SLOTS)) + C_SCOPE)) as usize] = st[(CUR) as usize];
    let brace: usize = find_either(w, a, e, B_LBRACE, B_APOS);
    if (brace != NONE) {
        reject(st, Y_EXPR, k, brace);
    } else {
        if (w[(t0) as usize] == B_DOT) {
            directive(w, st, k, t0, t1, e);
        } else {
            element(w, st, k, t0, t1, e);
        }
    }
}

pub fn scan(w: &[u8], st: &mut [usize]) -> () {
    let mut k: usize = 0;
    while (k < st[(SCAN_HI) as usize]) {
        scan_card(w, st, k);
        k = (k + 1);
    }
    if (st[(CUR) as usize] != NONE) {
        reject(st, Y_OPEN, st[(((DEF0 + (st[(CUR) as usize] * DEF_SLOTS)) + D_FIRST)) as usize], st[(((DEF0 + (st[(CUR) as usize] * DEF_SLOTS)) + D_NAME_A)) as usize]);
    }
    if (st[(CTL_CARD) as usize] != NONE) {
        reject(st, Y_CTLOPEN, st[(CTL_CARD) as usize], NONE);
    }
}

pub fn x_class(w: &[u8], st: &mut [usize], k: usize) -> usize {
    if !(xparse(w, st, k)) {
        return X_NONE;
    }
    let d: usize = find_def(w, st, st[(XA) as usize], st[(XB) as usize], st[(((CARD0 + (k * CARD_SLOTS)) + C_SCOPE)) as usize]);
    if (d != NONE) {
        return X_SUB;
    }
    return pdk_class(w, st[(XA) as usize], st[(XB) as usize]);
}

pub fn x_mult(w: &[u8], st: &mut [usize], k: usize) -> usize {
    let e: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize];
    let mut q: usize = st[(XP) as usize];
    while (q < e) {
        let t: usize = tk(w, q, e);
        if (t >= e) {
            return 1;
        }
        let te: usize = tk_end(w, t, e);
        let v: usize = tk(w, (tk(w, te, e) + 1), e);
        if ((ci_is(w, t, te, b"m") && parse_num(w, v, tk_end(w, v, e), st)) && whole_mult(st[(VM) as usize], st[(VE) as usize], st[(VS) as usize])) {
            return mult_value(st[(VM) as usize], st[(VE) as usize]);
        }
        q = tk_end(w, v, e);
    }
    return 1;
}

pub fn resolve(w: &[u8], st: &mut [usize]) -> () {
    let mut k: usize = 0;
    while (k < st[(SCAN_HI) as usize]) {
        let a: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_A)) as usize];
        let t0: usize = tk(w, a, st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize]);
        if ((((st[(((CARD0 + (k * CARD_SLOTS)) + C_SCOPE)) as usize] != SCOPE_CTL) && (w[(t0) as usize] != B_DOT)) && (lower(w[(t0) as usize]) == 120)) && xparse(w, st, k)) {
            let cls: usize = x_class(w, st, k);
            if (cls == X_SUB) {
                count(st, K_X);
                if (st[(XN) as usize] != st[(((DEF0 + (st[(DEF_HIT) as usize] * DEF_SLOTS)) + D_NPORTS)) as usize]) {
                    reject(st, Y_PORTS, k, st[(XA) as usize]);
                }
                if (st[(XP) as usize] < st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize]) {
                    check_params(w, st, k, st[(XP) as usize], st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize], 1, true);
                }
            } else {
                if (cls == X_NONE) {
                    reject(st, Y_UNDEF, k, st[(XA) as usize]);
                } else {
                    if (cls == X_MIM) {
                        count(st, K_MIM);
                        st[(N_MIM) as usize] = (st[(N_MIM) as usize] + 1);
                        if (st[(XN) as usize] != 2) {
                            reject(st, Y_PORTS, k, st[(XA) as usize]);
                        }
                    } else {
                        count(st, K_MOS);
                        if (cls == X_NMOS) {
                            st[(N_NMOS) as usize] = (st[(N_NMOS) as usize] + 1);
                        } else {
                            st[(N_PMOS) as usize] = (st[(N_PMOS) as usize] + 1);
                        }
                        if (st[(XN) as usize] != 4) {
                            reject(st, Y_PORTS, k, st[(XA) as usize]);
                        }
                    }
                }
            }
        }
        k = (k + 1);
    }
}

pub fn put_lower(w: &[u8], st: &mut [usize], out: &mut [u8], a: usize, b: usize) -> () {
    let mut i: usize = a;
    while (i < b) {
        put(st, out, lower(w[(i) as usize]));
        i = (i + 1);
    }
}

pub fn put_trail(w: &[u8], st: &mut [usize], out: &mut [u8], plen: usize) -> () {
    let mut i: usize = 0;
    while (i < plen) {
        put(st, out, w[((st[(WEND) as usize] + i)) as usize]);
        i = (i + 1);
    }
}

pub fn emit_leaf(w: &[u8], st: &mut [usize], out: &mut [u8], k: usize, plen: usize, kind: &[u8], weight: usize) -> () {
    let a: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_A)) as usize];
    put_trail(w, st, out, plen);
    put_lower(w, st, out, a, tk_end(w, a, st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize]));
    puts(st, out, b" ");
    puts(st, out, kind);
    if (weight > 0) {
        puts(st, out, b" ");
        put_lower(w, st, out, st[(XA) as usize], st[(XB) as usize]);
        puts(st, out, b" m=");
        put_num(st, out, weight);
    }
    put(st, out, B_NL);
}

pub fn flatten(w: &mut [u8], st: &mut [usize], out: &mut [u8], scope: usize, lo: usize, hi: usize, plen: usize, depth: usize, mult: usize) -> () {
    if (depth > st[(DEPTH_SEEN) as usize]) {
        st[(DEPTH_SEEN) as usize] = depth;
    }
    if ((depth > 0) && (depth <= MAX_DEPTH)) {
        st[(((STK + depth) - 1)) as usize] = scope;
    }
    let mut k: usize = lo;
    while (k < hi) {
        let a: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_A)) as usize];
        let e: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize];
        let t0: usize = tk(w, a, e);
        if ((st[(((CARD0 + (k * CARD_SLOTS)) + C_SCOPE)) as usize] == scope) && (w[(t0) as usize] != B_DOT)) {
            let c: u8 = lower(w[(t0) as usize]);
            let mut kind: usize = K_COUNT;
            let mut label: &'static str = "";
            if (c == 114) {
                kind = K_R;
                label = "r";
            }
            if (c == 99) {
                kind = K_C;
                label = "c";
            }
            if (c == 108) {
                kind = K_L;
                label = "l";
            }
            if (c == 118) {
                kind = K_V;
                label = "v";
            }
            if (c == 105) {
                kind = K_I;
                label = "i";
            }
            if (c == 101) {
                kind = K_E;
                label = "e";
            }
            if (kind < K_COUNT) {
                if (st[(EMIT) as usize] == 0) {
                    st[((FLAT + kind)) as usize] = (st[((FLAT + kind)) as usize] + 1);
                } else {
                    emit_leaf(w, st, out, k, plen, label.as_bytes(), 0);
                }
            } else {
                if (c == 120) {
                    let cls: usize = x_class(w, st, k);
                    if (cls == X_SUB) {
                        let d: usize = st[(DEF_HIT) as usize];
                        let nm: usize = (mult * x_mult(w, st, k));
                        let nl: usize = (tk_end(w, t0, e) - t0);
                        let mut open: bool = false;
                        let mut j: usize = 0;
                        while ((j < depth) && (j < MAX_DEPTH)) {
                            if (st[((STK + j)) as usize] == d) {
                                open = true;
                            }
                            j = (j + 1);
                        }
                        if open {
                            reject(st, Y_RECUR, k, st[(XA) as usize]);
                        } else {
                            if (depth >= MAX_DEPTH) {
                                reject(st, Y_DEPTH, k, st[(XA) as usize]);
                            } else {
                                if (nm > MAX_MULT) {
                                    reject(st, Y_MULT, k, NONE);
                                } else {
                                    if ((((st[(WEND) as usize] + plen) + nl) + 1) > w.len()) {
                                        reject(st, Y_SIZE, k, NONE);
                                    } else {
                                        if (st[(EMIT) as usize] == 0) {
                                            st[((FLAT + K_X)) as usize] = (st[((FLAT + K_X)) as usize] + 1);
                                        }
                                        let mut i: usize = 0;
                                        while (i < nl) {
                                            w[(((st[(WEND) as usize] + plen) + i)) as usize] = lower(w[((t0 + i)) as usize]);
                                            i = (i + 1);
                                        }
                                        w[(((st[(WEND) as usize] + plen) + nl)) as usize] = B_DOT;
                                        flatten(w, st, out, d, (st[(((DEF0 + (d * DEF_SLOTS)) + D_FIRST)) as usize] + 1), st[(((DEF0 + (d * DEF_SLOTS)) + D_LAST)) as usize], ((plen + nl) + 1), (depth + 1), nm);
                                    }
                                }
                            }
                        }
                    } else {
                        if (cls != X_NONE) {
                            let weight: usize = (mult * x_mult(w, st, k));
                            if (weight > MAX_MULT) {
                                reject(st, Y_MULT, k, NONE);
                            } else {
                                if (st[(EMIT) as usize] == 0) {
                                    if (cls == X_MIM) {
                                        st[((FLAT + K_MIM)) as usize] = (st[((FLAT + K_MIM)) as usize] + 1);
                                        st[(FLAT_MIM_W) as usize] = (st[(FLAT_MIM_W) as usize] + weight);
                                    } else {
                                        st[((FLAT + K_MOS)) as usize] = (st[((FLAT + K_MOS)) as usize] + 1);
                                        st[(FLAT_MOS_W) as usize] = (st[(FLAT_MOS_W) as usize] + weight);
                                    }
                                } else {
                                    if (cls == X_MIM) {
                                        emit_leaf(w, st, out, k, plen, b"mim", weight);
                                    } else {
                                        emit_leaf(w, st, out, k, plen, b"mos", weight);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        k = (k + 1);
    }
}

pub fn put_val(st: &mut [usize], out: &mut [u8]) -> () {
    if (st[(VS) as usize] != 0) {
        put(st, out, B_MINUS);
    }
    put_num(st, out, st[(VM) as usize]);
    if (((st[(VM) as usize] != 0) && (st[(VE) as usize] > EXP_BIAS)) && ((st[(VE) as usize] - EXP_BIAS) <= 9)) {
        let mut z: usize = (st[(VE) as usize] - EXP_BIAS);
        while (z > 0) {
            put(st, out, B_ZERO);
            z = (z - 1);
        }
    } else {
        if ((st[(VM) as usize] != 0) && (st[(VE) as usize] != EXP_BIAS)) {
            puts(st, out, b"e");
            if (st[(VE) as usize] < EXP_BIAS) {
                put(st, out, B_MINUS);
                put_num(st, out, (EXP_BIAS - st[(VE) as usize]));
            } else {
                put_num(st, out, (st[(VE) as usize] - EXP_BIAS));
            }
        }
    }
}

pub fn put_tok(w: &[u8], st: &mut [usize], out: &mut [u8], t: usize, e: usize) -> () {
    put_text(w, st, out, t, tk_end(w, t, e), SHOW);
}

pub fn put_kv(st: &mut [usize], out: &mut [u8], key: &[u8], v: usize) -> () {
    puts(st, out, key);
    put_num(st, out, v);
}

pub fn put_why(w: &[u8], st: &mut [usize], out: &mut [u8]) -> () {
    let why: usize = st[(ERR_WHY) as usize];
    let k: usize = st[(ERR_CARD) as usize];
    let tok: usize = st[(ERR_TOK) as usize];
    if (why == Y_CONT) {
        puts(st, out, b"continuation line with no card before it");
    } else {
        if (why == Y_SIZE) {
            puts(st, out, b"deck is larger than the reader's tables");
        } else {
            if (why == Y_B) {
                puts(st, out, b"B source not supported");
            } else {
                if (why == Y_ELEMENT) {
                    let c: u8 = lower(w[(st[(((CARD0 + (k * CARD_SLOTS)) + C_A)) as usize]) as usize]);
                    if ((c >= 97) && (c <= 122)) {
                        put(st, out, (c - 32));
                    } else {
                        put(st, out, c);
                    }
                    puts(st, out, b" element not supported");
                } else {
                    if (why == Y_DIRECTIVE) {
                        put_tok(w, st, out, st[(((CARD0 + (k * CARD_SLOTS)) + C_A)) as usize], st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize]);
                        puts(st, out, b" directive not supported");
                    } else {
                        if (why == Y_EXPR) {
                            puts(st, out, b"expression in braces or quotes not supported");
                        } else {
                            if (why == Y_FIELDS) {
                                puts(st, out, b"wrong number of fields");
                            } else {
                                if (why == Y_E) {
                                    puts(st, out, b"E source must be a VCVS: name n+ n- nc+ nc- gain");
                                } else {
                                    if (why == Y_SUBPARAM) {
                                        puts(st, out, b"subcircuit parameters not supported");
                                    } else {
                                        if (why == Y_ENDS) {
                                            puts(st, out, b".ends does not close a .subckt");
                                        } else {
                                            if (why == Y_CTLOPEN) {
                                                puts(st, out, b".control without .endc");
                                            } else {
                                                if (why == Y_CTLIN) {
                                                    puts(st, out, b".control inside a .subckt not supported");
                                                } else {
                                                    if (why == Y_MULT) {
                                                        puts(st, out, b"m must be a whole number from 1 to 1000000000");
                                                    } else {
                                                        if (why == Y_NUMBER) {
                                                            puts(st, out, b"not a literal number");
                                                        }
                                                        if (why == Y_PARAM) {
                                                            puts(st, out, b"parameter not supported");
                                                        }
                                                        if (why == Y_SOURCE) {
                                                            puts(st, out, b"source form not supported");
                                                        }
                                                        if (why == Y_UNDEF) {
                                                            puts(st, out, b"subcircuit or device model not defined");
                                                        }
                                                        if (why == Y_PORTS) {
                                                            puts(st, out, b"node count differs from the ports of");
                                                        }
                                                        if (why == Y_DEPTH) {
                                                            puts(st, out, b"subcircuit nesting deeper than 32 levels");
                                                        }
                                                        if (why == Y_RECUR) {
                                                            puts(st, out, b"subcircuit instantiates itself");
                                                        }
                                                        if (why == Y_OPEN) {
                                                            puts(st, out, b".subckt without .ends");
                                                        }
                                                        if (why == Y_DUP) {
                                                            puts(st, out, b"subcircuit defined twice");
                                                        }
                                                        if (why == Y_CTL) {
                                                            puts(st, out, b"control command not supported");
                                                        }
                                                        if (why == Y_OPTION) {
                                                            puts(st, out, b"option not supported (only TEMP)");
                                                        }
                                                        if ((tok != NONE) && (k != NONE)) {
                                                            puts(st, out, b": ");
                                                            put_tok(w, st, out, tok, st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize]);
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn put_reject(w: &[u8], st: &mut [usize], out: &mut [u8]) -> () {
    puts(st, out, b"line ");
    put_num(st, out, st[(ERR_LINE) as usize]);
    puts(st, out, b": ");
    put_why(w, st, out);
    put(st, out, B_NL);
    if (st[(ERR_CARD) as usize] != NONE) {
        puts(st, out, b"  card: ");
        put_text(w, st, out, st[(((CARD0 + (st[(ERR_CARD) as usize] * CARD_SLOTS)) + C_A)) as usize], st[(((CARD0 + (st[(ERR_CARD) as usize] * CARD_SLOTS)) + C_B)) as usize], SHOW);
        put(st, out, B_NL);
    }
}

pub fn put_tran(w: &[u8], st: &mut [usize], out: &mut [u8], k: usize, t1: usize, label: &[u8]) -> () {
    let e: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize];
    let a: usize = tk(w, t1, e);
    let b: usize = tk(w, tk_end(w, a, e), e);
    puts(st, out, label);
    puts(st, out, b" ");
    put_tok(w, st, out, a, e);
    puts(st, out, b" ");
    put_tok(w, st, out, b, e);
    puts(st, out, b": tstep ");
    if parse_num(w, a, tk_end(w, a, e), st) {
        put_val(st, out);
    }
    puts(st, out, b" tstop ");
    if parse_num(w, b, tk_end(w, b, e), st) {
        put_val(st, out);
    }
    puts(st, out, b" (line ");
    put_num(st, out, st[(((CARD0 + (k * CARD_SLOTS)) + C_LINE)) as usize]);
    puts(st, out, b")\n");
}

pub fn put_recorded(w: &[u8], st: &mut [usize], out: &mut [u8]) -> () {
    let mut corners: usize = 0;
    let mut k: usize = 0;
    while (k < st[(SCAN_HI) as usize]) {
        let a: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_A)) as usize];
        let e: usize = st[(((CARD0 + (k * CARD_SLOTS)) + C_B)) as usize];
        let t0: usize = tk(w, a, e);
        let t1: usize = tk_end(w, t0, e);
        if (st[(((CARD0 + (k * CARD_SLOTS)) + C_SCOPE)) as usize] == SCOPE_CTL) {
            if ci_is(w, t0, t1, b"tran") {
                put_tran(w, st, out, k, t1, b"tran (control)");
            }
        } else {
            if ci_is(w, t0, t1, b".tran") {
                put_tran(w, st, out, k, t1, b"tran (.tran card)");
            } else {
                if ci_is(w, t0, t1, b".lib") {
                    puts(st, out, b"corner: ");
                    put_tok(w, st, out, word_at(w, t1, e, 1), e);
                    puts(st, out, b" from ");
                    put_tok(w, st, out, word_at(w, t1, e, 0), e);
                    puts(st, out, b" (not read)\n");
                    corners = (corners + 1);
                } else {
                    if dir_is(w, t0, t1, b".include", b".inc") {
                        puts(st, out, b"include: ");
                        put_tok(w, st, out, word_at(w, t1, e, 0), e);
                        puts(st, out, b" (not read)\n");
                    }
                }
            }
        }
        k = (k + 1);
    }
    if (corners == 0) {
        puts(st, out, b"corners: none\n");
    }
    if (st[(TEMP_CARD) as usize] == NONE) {
        puts(st, out, b"temp: none\n");
    } else {
        let tc: usize = st[(TEMP_CARD) as usize];
        let e: usize = st[(((CARD0 + (tc * CARD_SLOTS)) + C_B)) as usize];
        let mut q: usize = tk_end(w, st[(((CARD0 + (tc * CARD_SLOTS)) + C_A)) as usize], e);
        let mut go: bool = true;
        while go {
            let t: usize = tk(w, q, e);
            if (t >= e) {
                go = false;
            } else {
                if ci_is(w, t, tk_end(w, t, e), b"temp") {
                    let v: usize = tk(w, (tk(w, tk_end(w, t, e), e) + 1), e);
                    if parse_num(w, v, tk_end(w, v, e), st) {
                        puts(st, out, b"temp: ");
                        put_val(st, out);
                        puts(st, out, b"\n");
                    }
                    go = false;
                } else {
                    q = tk_end(w, t, e);
                }
            }
        }
    }
}

pub fn put_inventory(src: &[u8], w: &mut [u8], st: &mut [usize], out: &mut [u8]) -> () {
    puts(st, out, b"deck: ");
    put_text(src, st, out, st[(TITLE_A) as usize], st[(TITLE_B) as usize], SHOW);
    puts(st, out, b"\nend: ");
    if (st[(END_N) as usize] == 0) {
        puts(st, out, b"no .end card");
    } else {
        puts(st, out, b"first .end on line ");
        put_num(st, out, st[(END_LINE) as usize]);
        puts(st, out, b", the deck ends with the last of ");
        put_num(st, out, st[(END_N) as usize]);
        puts(st, out, b", cards after it ignored: ");
        put_num(st, out, st[(IGNORED) as usize]);
    }
    puts(st, out, b"\ncards: ");
    put_kv(st, out, b"r=", st[((SRC + K_R)) as usize]);
    put_kv(st, out, b" c=", st[((SRC + K_C)) as usize]);
    put_kv(st, out, b" l=", st[((SRC + K_L)) as usize]);
    put_kv(st, out, b" v=", st[((SRC + K_V)) as usize]);
    put_kv(st, out, b" i=", st[((SRC + K_I)) as usize]);
    put_kv(st, out, b" e=", st[((SRC + K_E)) as usize]);
    put_kv(st, out, b" x=", st[(N_XCARDS) as usize]);
    put_kv(st, out, b" (subcircuit instances ", st[((SRC + K_X)) as usize]);
    put_kv(st, out, b", mos ", st[((SRC + K_MOS)) as usize]);
    put_kv(st, out, b", mim ", st[((SRC + K_MIM)) as usize]);
    puts(st, out, b")\nsources: ");
    put_kv(st, out, b"dc=", st[((WAVE + WV_DC)) as usize]);
    put_kv(st, out, b" pulse=", st[((WAVE + WV_PULSE)) as usize]);
    put_kv(st, out, b" sin=", st[((WAVE + WV_SIN)) as usize]);
    put_kv(st, out, b" pwl=", st[((WAVE + WV_PWL)) as usize]);
    puts(st, out, b"\nsubckt definitions: ");
    put_num(st, out, st[(NDEF) as usize]);
    put(st, out, B_NL);
    let mut d: usize = 0;
    while (d < st[(NDEF) as usize]) {
        puts(st, out, b"  subckt ");
        put_lower(w, st, out, st[(((DEF0 + (d * DEF_SLOTS)) + D_NAME_A)) as usize], st[(((DEF0 + (d * DEF_SLOTS)) + D_NAME_B)) as usize]);
        put_kv(st, out, b" ports=", st[(((DEF0 + (d * DEF_SLOTS)) + D_NPORTS)) as usize]);
        if (st[(((DEF0 + (d * DEF_SLOTS)) + D_PARENT)) as usize] != NONE) {
            puts(st, out, b" inside ");
            put_lower(w, st, out, st[(((DEF0 + (st[(((DEF0 + (d * DEF_SLOTS)) + D_PARENT)) as usize] * DEF_SLOTS)) + D_NAME_A)) as usize], st[(((DEF0 + (st[(((DEF0 + (d * DEF_SLOTS)) + D_PARENT)) as usize] * DEF_SLOTS)) + D_NAME_B)) as usize]);
        }
        put(st, out, B_NL);
        d = (d + 1);
    }
    put_kv(st, out, b"mos: sg13_lv_nmos=", st[(N_NMOS) as usize]);
    put_kv(st, out, b" sg13_lv_pmos=", st[(N_PMOS) as usize]);
    put_kv(st, out, b" total=", st[((SRC + K_MOS)) as usize]);
    put_kv(st, out, b"\nmim: cap_cmim=", st[(N_MIM) as usize]);
    put(st, out, B_NL);
    put_recorded(w, st, out);
    puts(st, out, b"recorded, not evaluated: ");
    put_kv(st, out, b"lib=", st[(N_LIB) as usize]);
    put_kv(st, out, b" include=", st[(N_INC) as usize]);
    put_kv(st, out, b" parameters=", st[(N_PARAM) as usize]);
    put_kv(st, out, b" options=", st[(N_OPT) as usize]);
    put_kv(st, out, b" ic=", st[(N_IC) as usize]);
    put_kv(st, out, b" nodeset=", st[(N_NODESET) as usize]);
    put_kv(st, out, b" save=", st[(N_SAVE) as usize]);
    put_kv(st, out, b" global=", st[(N_GLOBAL) as usize]);
    put_kv(st, out, b" control-commands=", st[(N_CTLCMD) as usize]);
    puts(st, out, b"\nflattened: ");
    put_kv(st, out, b"instances=", (((((((st[((FLAT + K_R)) as usize] + st[((FLAT + K_C)) as usize]) + st[((FLAT + K_L)) as usize]) + st[((FLAT + K_V)) as usize]) + st[((FLAT + K_I)) as usize]) + st[((FLAT + K_E)) as usize]) + st[((FLAT + K_MOS)) as usize]) + st[((FLAT + K_MIM)) as usize]));
    put_kv(st, out, b" r=", st[((FLAT + K_R)) as usize]);
    put_kv(st, out, b" c=", st[((FLAT + K_C)) as usize]);
    put_kv(st, out, b" l=", st[((FLAT + K_L)) as usize]);
    put_kv(st, out, b" v=", st[((FLAT + K_V)) as usize]);
    put_kv(st, out, b" i=", st[((FLAT + K_I)) as usize]);
    put_kv(st, out, b" e=", st[((FLAT + K_E)) as usize]);
    put_kv(st, out, b" mos=", st[((FLAT + K_MOS)) as usize]);
    put_kv(st, out, b" mim=", st[((FLAT + K_MIM)) as usize]);
    put_kv(st, out, b" levels=", st[((FLAT + K_X)) as usize]);
    put_kv(st, out, b" depth=", st[(DEPTH_SEEN) as usize]);
    puts(st, out, b"\nflattened, weighted by m: ");
    put_kv(st, out, b"mos=", st[(FLAT_MOS_W) as usize]);
    put_kv(st, out, b" mim=", st[(FLAT_MIM_W) as usize]);
    puts(st, out, b"\ninstances:\n");
    st[(EMIT) as usize] = 1;
    flatten(w, st, out, NONE, 0, st[(SCAN_HI) as usize], 0, 0, 1);
}

pub fn inventory(src: &[u8], w: &mut [u8], out: &mut [u8], st: &mut [usize]) -> usize {
    st[(END_LAST) as usize] = NONE;
    st[(CUR) as usize] = NONE;
    st[(CTL_CARD) as usize] = NONE;
    st[(TEMP_CARD) as usize] = NONE;
    st[(DEF_HIT) as usize] = NONE;
    prepare(src, w, st);
    mark_end(w, st);
    scan(w, st);
    resolve(w, st);
    st[(EMIT) as usize] = 0;
    flatten(w, st, out, NONE, 0, st[(SCAN_HI) as usize], 0, 0, 1);
    if (st[(ERR_LINE) as usize] != 0) {
        put_reject(w, st, out);
    } else {
        put_inventory(src, w, st, out);
    }
    return st[(W) as usize];
}

pub fn has_text(w: usize, out: &[u8], needle: &[u8]) -> bool {
    let mut i: usize = 0;
    while ((i + needle.len()) <= w) {
        let mut k: usize = 0;
        while ((k < needle.len()) && (out[((i + k)) as usize] == needle[(k) as usize])) {
            k = (k + 1);
        }
        if (k == needle.len()) {
            return true;
        }
        i = (i + 1);
    }
    return false;
}

pub const B_DEL: u8 = 127;

pub const B_LOWER_A: u8 = 97;

pub const B_LOWER_Z: u8 = 122;

pub const B_NINE: u8 = 57;

pub const B_UNDERSCORE: u8 = 95;

pub const B_UPPER_A: u8 = 65;

pub const B_UPPER_Z: u8 = 90;

pub fn is_alpha(c: u8) -> bool {
    return ((((c >= B_LOWER_A) && (c <= B_LOWER_Z)) || is_upper(c)) || (c == B_UNDERSCORE));
}

pub fn is_digit(c: u8) -> bool {
    return ((c >= B_ZERO) && (c <= B_NINE));
}

pub fn is_space(c: u8) -> bool {
    return ((((c == B_SPACE) || (c == B_TAB)) || (c == B_NL)) || (c == B_CR));
}

pub fn is_upper(c: u8) -> bool {
    return ((c >= B_UPPER_A) && (c <= B_UPPER_Z));
}

pub fn out_is(w: usize, out: &[u8], from: usize, s: &[u8]) -> bool {
    if (((w < from) || ((w - from) != s.len())) || (w > out.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < s.len()) {
        if (out[((from + k)) as usize] != s[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn put(st: &mut [usize], out: &mut [u8], c: u8) -> () {
    let w: usize = st[(W) as usize];
    if (w < out.len()) {
        out[(w) as usize] = c;
    }
    st[(W) as usize] = (w + 1);
}

pub fn put_num(st: &mut [usize], out: &mut [u8], v: usize) -> () {
    if (v >= 10) {
        put_num(st, out, (v / 10));
    }
    put(st, out, (B_ZERO + ((v % 10) as u8)));
}

pub fn put_text(src: &[u8], st: &mut [usize], out: &mut [u8], a: usize, b: usize, max: usize) -> () {
    let mut i: usize = a;
    while (((i < b) && (i < src.len())) && (i < (a + max))) {
        let c: u8 = src[(i) as usize];
        if ((c >= B_SPACE) && (c < B_DEL)) {
            put(st, out, c);
        } else {
            if ((c < 128) || (c >= 192)) {
                put(st, out, 63);
            }
        }
        i = (i + 1);
    }
}

pub fn puts(st: &mut [usize], out: &mut [u8], s: &[u8]) -> () {
    let mut i: usize = 0;
    while (i < s.len()) {
        put(st, out, s[(i) as usize]);
        i = (i + 1);
    }
}

